package com.ruoyi.medical.persistence;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static com.ruoyi.medical.persistence.FormalInputFixture.*;import java.util.*;import com.ruoyi.medical.contracts.*;
final class FormalEvaluationInputCandidatesTest {
 @Test void realPurposeAuthorityReturnsMetadataWithoutGetWritesOrSourceReadingGrant()throws Exception{try(var f=new FormalInputFixture()){doAnswer(i->{Map<String,Object> v=i.getArgument(0);assertEquals(ACTOR,v.get("userId"));assertEquals(PURPOSE,v.get("purpose"));assertEquals(0,v.get("offset"));TenantScope.requireSubjectParameter("com.ruoyi.medical.persistence.mapper.FormalEvaluationInputMapper.candidateVersions",v);return List.of(SOURCE);}).when(f.mapper).candidateVersions(anyMap());var v=f.service.candidates(f.subject,"1",PURPOSE,"0");assertEquals(1,v.path("items").size());var c=v.path("items").get(0);assertEquals(SOURCE,c.path("source").path("version_id").asText());assertEquals(RIGHTS,c.path("rights_revision").asText());assertEquals("NOT_READ",c.path("content_validation").asText());assertEquals(0,f.requests.get());assertTrue(f.writes.isEmpty());assertTrue(v.path("next_offset").isNull());}}
 @Test void missingActualRegisterGrantDoesNotExposeCandidate()throws Exception{try(var f=new FormalInputFixture()){doReturn(List.of(SOURCE)).when(f.mapper).candidateVersions(anyMap());f.grants.removeIf(g->g.action().equals("artifact.register"));assertEquals(0,f.service.candidates(f.subject,"1",PURPOSE,"0").path("items").size());assertEquals(0,f.requests.get());assertTrue(f.writes.isEmpty());}}
 @Test void callerCannotReplaceActualPurposeOrUseProjectSource()throws Exception{try(var f=new FormalInputFixture()){doReturn(List.of(SOURCE)).when(f.mapper).candidateVersions(anyMap());assertEquals(0,f.service.candidates(f.subject,"1","OTHER","0").path("items").size());var s=f.sourceRows.get(SOURCE);f.sourceRows.put(SOURCE,new SourceReadProtocol.SourceRow(s.tenantId(),s.sourceId(),s.sourceVersion(),id(77),"PROJECT",s.classification(),s.rightsRevision(),s.originalSha256(),s.registeredSha256(),id(77)));assertEquals(0,f.service.candidates(f.subject,"1",PURPOSE,"0").path("items").size());assertTrue(f.writes.isEmpty());}}
 @Test void malformedBoundsAndStaleContextRejectedBeforeRead()throws Exception{try(var f=new FormalInputFixture()){for(String offset:List.of("-1","01","1000000","1.0"))assertThrows(Exception.class,()->f.service.candidates(f.subject,"1",PURPOSE,offset));assertThrows(Exception.class,()->f.service.candidates(f.subject,"1","other","0"));assertThrows(Exception.class,()->f.service.candidates(f.subject,"2",PURPOSE,"0"));verify(f.mapper,never()).candidateVersions(anyMap());}}
 @Test void oversizeAndUnapprovedAreSkippedWithoutTransport()throws Exception{try(var f=new FormalInputFixture()){doReturn(List.of(SOURCE)).when(f.mapper).candidateVersions(anyMap());var o=f.original;f.original=new FormalEvaluationInputProtocol.Original(o.tenantId(),o.sourceVersion(),o.sha256(),o.objectKey(),o.objectVersion(),java.math.BigInteger.valueOf(2097153),o.mediaType());assertEquals(0,f.service.candidates(f.subject,"1",PURPOSE,"0").path("items").size());assertEquals(0,f.requests.get());}}
 @Test void boundedScanRejectsDuplicateOrOversizedMapperPages()throws Exception{try(var f=new FormalInputFixture()){doReturn(List.of(SOURCE,SOURCE)).when(f.mapper).candidateVersions(anyMap());assertThrows(Exception.class,()->f.service.candidates(f.subject,"1",PURPOSE,"0"));doReturn(java.util.stream.IntStream.range(1,23).mapToObj(FormalInputFixture::id).toList()).when(f.mapper).candidateVersions(anyMap());assertThrows(Exception.class,()->f.service.candidates(f.subject,"1",PURPOSE,"0"));assertEquals(0,f.requests.get());}}
}
